  for (int i = 0; i < app->num_species; ++i) {
    gk_species_source_rhs(app, &app->species[i], &app->species[i].src, fin[i], fout[i]);
  }
  for (int i = 0; i < app->num_neut_species; ++i) {
    gk_neut_species_source_rhs(
