static void
gk_species_calc_fdot_mom_enabled(gkyl_gyrokinetic_app *app, struct gk_species *gks)
{
  struct timespec wst = gkyl_wall_clock();
  gkyl_array_accumulate(gks->fdot_mom_new, -1.0, gks->fdot_mom_old);
